SELECT 'storyboard:catpope:4', 'storyboard', 'catpope', NULL, '{"storyboard":2,"toon":"catpope","chapter":4,"scenes":[{"storyboard":2,"toon":"catpope","chapter":4,"source":{"script":"script:catpope:de","scene":35,"heading":"INT./EXT. GRUFT","lines":[1478,1505]},"cast":[{"ref":"plf","character":"catpope","persona":"human","look":"default"},{"ref":"crows","character":"crows","persona":"regular","look":"default"}],"locations":[{"ref":"crypt","place":"crypt","time":"day"},{"ref":"graveyard","place":"graveyard","time":"day"}],"light":{"key":"top-left","height":"high","source":"sun","shadow":"short","soft":0.5,"note":{"de":"Klarer Himmel, harte Sonne von links oben: weiße Grabsteine, schwarze Schlagschatten wie ausgeschnitten – zu sauber, um echt zu sein."}},"groups":[{"label":"scene-35","renderer":{"type":"vertical"},"continues":true,"shots":[{"id":"sb-35-0","title":true,"format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"eye"},"location":"crypt","view":"narration","light":{"source":"none","note":{"de":"Schwarz – nur der Titel."}},"action":{"de":"Der Kapiteltitel auf Schwarz, wie in Kapitel 2: oben klein „4. KAPITEL“, darunter groß „DEPRESSION“ – die 4. Phase der Trauer."},"figures":[],"dialog":[{"variant":"caption","font":"lettering","title":true,"size":9,"rect":{"x":10,"y":36,"width":80},"text":{"de":"4. KAPITEL"}},{"variant":"caption","font":"lettering","title":true,"size":18,"rect":{"x":4,"y":44,"width":92},"text":{"de":"“DEPRESSION”"}}],"source":{"want":"art"},"status":"draft"},{"id":"sb-35-1","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"full","angle":"low"},"location":"crypt","view":"real","light":{"key":"back","height":"eye","source":"sun","shadow":"long","rim":true,"soft":0.3,"note":{"de":"Gegenlicht durch die Gruftöffnung: PLF ein schwarzer Umriss mit weißem Rand, hinter ihr das ausgebrannte Weiß des Tages, vorne pechschwarze Gruft."}},"action":{"de":"Aus dem Inneren der Gruft gesehen: Stufen hinauf zur offenen, schiefen Gruftpforte. PLF im zerrissenen weißen Gewand tritt hinaus ins Licht, von hinten, ein Fuß schon auf der obersten Stufe. Ihr Schatten fällt lang die Stufen herunter, zurück ins Dunkel."},"air":[[0,22]],"figures":[{"cast":"plf","framing":"full","mood":"sad","pose":"walk","facing":"away","x":0.5,"y":0.5,"h":0.45}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":60},"text":{"de":"35 INT./EXT. GRUFT"}},{"variant":"narration","font":"mono","rect":{"x":8,"y":78,"width":70},"text":{"de":"PLF trat aus der Gruft hinaus, die Dunkelheit noch in ihren Gedanken nachhallend."}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Kapitelanfang: oben Schwarz der Gruft als Luft. Anschluss an sb-34-7 (PLF am Fuß der Gruft) – hier der Austritt noch einmal von innen, damit Kapitel 4 mit der Dunkelheit beginnt."},{"id":"sb-35-2","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"ews","angle":"high"},"location":"graveyard","view":"real","light":{"note":{"de":"Steile Mittagssonne: jeder Grabstein wirft einen kurzen, scharfen Schatten – ein Muster wie gestanzt."}},"action":{"de":"Vom leeren, klaren Himmel hinab über eine Zypresse auf einen kleinen ummauerten Friedhof: schiefe Grabsteine in Reihen, ein schmiedeeisernes Tor in der Ferne, kein Vogel, kein Wind. Ganz unten winzig PLF vor der Gruft."},"air":[[0,40]],"figures":[{"cast":"plf","framing":"full","mood":"neutral","pose":"stand","facing":"front","x":0.42,"y":0.9,"h":0.08}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":40,"y":52,"width":54},"text":{"de":"… und stand nun inmitten der gespenstischen Stille des Friedhofs."}}],"source":{"type":"schematic","want":"photo"},"status":"draft","note":"Die Stille ist das Bild: viel leerer Himmel, der Friedhof wie eingefroren."},{"id":"sb-35-3","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"mcu","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"left","height":"low","note":{"de":"Streiflicht von links reißt die Kratzer im Gesicht heraus; die rechte Gesichtshälfte versinkt in Schwarz, dort hängen die Krähen."}},"action":{"de":"PLF im Halbprofil, Kratzer an Wange und Hals, verklebte Haare, der Blick nach innen. Hinter ihr in den schwarzen Schatten als weiße Liniengrafik die Krähenwesen, die sich lachend zurückziehen: aufgerissene Schnäbel, Lach-Linien, die sich um PLFs Kopf winden."},"air":[[0,12]],"figures":[{"cast":"plf","framing":"mcu","mood":"sad","pose":"stand","facing":"three-quarter-left","x":0.38,"y":0.6,"h":0.7},{"cast":"crows","framing":"full","mood":"laughing","pose":"stand","facing":"front","x":0.78,"y":0.25,"h":0.2,"note":"nur als weiße Linien-Erinnerung im Schatten"}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":14,"width":62},"text":{"de":"Der Kampf mit den Krähenwesen hatte sie schwer gezeichnet, nicht nur äußerlich."}},{"variant":"narration","font":"mono","rect":{"x":34,"y":80,"width":60},"text":{"de":"Ihr boshaftes Lachen hallte noch immer in ihren Ohren. Sie wussten etwas, das ihr verborgen blieb."}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Die Krähen als Liniengrafik im Stil der Wolken aus Kapitel 1/2 – Nachhall, nicht anwesend. Das Lachen steht im Skript ohne {…}, daher Erzählung statt SFX."},{"id":"sb-35-4","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"cu","angle":"high"},"location":"crypt","view":"real","light":{"key":"top-left","height":"high","shadow":"short","note":{"de":"Harte Sonne auf Stoff und Stein: der Riss im Saum als schwarze Kerbe, die Feder ein tiefschwarzer Schnitt auf weißem Stein."}},"action":{"de":"Detail, von oben nach unten: der zerrissene Saum des weißen Gewands, Brandspuren vom Kampf; darunter PLFs nackter Fuß auf der Gruftstufe; daneben eine einzelne schwarze Krähenfeder, die leicht zittert, obwohl kein Wind geht."},"air":[[0,18],[85,100]],"figures":[{"cast":"plf","framing":"medium","mood":"sad","pose":"stand","facing":"front","x":0.45,"y":0.35,"h":0.9}],"dialog":[],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Stilles Detail (geplante Stille): die Spuren des Kampfs, bevor die Erzählung weitergeht. Die zitternde Feder ohne Wind ist der erste, kaum merkliche Glitch."},{"id":"sb-35-5","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"ews","angle":"bird"},"location":"graveyard","view":"real","light":{"key":"top-left","height":"high","note":{"de":"Von oben: die Wege des Friedhofs als weiße Linien zwischen schwarzen Schattenblöcken – ein Schaltplan."}},"action":{"de":"Senkrecht von oben: der Friedhof als Muster. Die Kieswege zwischen den Gräbern bilden ein riesiges, unvollständiges Ornament (wie eine Leiterplatte), PLF ein winziger weißer Punkt auf einem Teilstück davon. Das Muster läuft über den Bildrand hinaus."},"air":[[0,10]],"figures":[{"cast":"plf","framing":"full","mood":"thinking","pose":"stand","facing":"front","x":0.36,"y":0.62,"h":0.03}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":8,"y":76,"width":72},"text":{"de":"Der Sieg fühlte sich hohl an – als hätte sie nur einen kleinen Teil eines viel größeren, ungreifbaren Ganzen errungen."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Vorahnung des Systems (Leiterplatte, Serverfarm aus Kapitel 3) ohne es zu sagen.","prompt":{"en":"Top-down bird\'s-eye view of a small walled graveyard at noon: the gravel paths between rows of headstones form a huge, unfinished geometric pattern like a circuit board that runs off the edges of the frame. A tiny person in a white robe stands on one short piece of the pattern. Hard sun, crisp short black shadows."}},{"id":"sb-35-6","format":"vertical","aspect":"1:4","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"low"},"location":"graveyard","view":"real","light":{"key":"top-left","height":"high","note":{"de":"Der klare Himmel als weiße Fläche, durch die schwarze Störstreifen laufen; unten PLF scharf gegen das Licht."}},"action":{"de":"Klarer, wolkenloser Himmel, durch den waagrechte Störbänder laufen: Streifen des Himmels um ein paar Pixel versetzt, eine Zeile Sonne doppelt, Treppenstufen-Kanten an der Zypressenspitze. Nach unten wird das Bild ruhig – PLF blickt hoch, die Hand über den Augen."},"air":[[0,30]],"figures":[{"cast":"plf","framing":"medium","mood":"confused","pose":"stand","facing":"three-quarter-right","x":0.5,"y":0.88,"h":0.45}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":34,"width":64},"text":{"de":"Der Himmel war klar, doch die Realität um sie herum flackerte wie ein gestörter Bildschirm."}},{"variant":"narration","font":"mono","rect":{"x":40,"y":58,"width":54},"text":{"de":"Ein Glitch, ein Fehler im Gewebe der Wirklichkeit."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Glitch-Sprache für Schwarzweiß: versetzte Bildstreifen, Pixelblöcke, Treppenkanten, Zeilensprünge – kein RGB-Versatz (nur Schwarz/Weiß). Grafik über ein Friedhofsfoto."},{"id":"sb-35-7","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"real","light":{"note":{"de":"Gleiche Sonne, aber die Schatten der doppelten Bäume zeigen in zwei Richtungen – ein Fehler, den man erst beim zweiten Blick sieht."}},"action":{"de":"PLF reibt sich mit beiden Händen die Augen. Hinter ihr die Baumreihe an der Friedhofsmauer zweimal, leicht versetzt übereinander wie ein verrutschter Druck; die Schatten der zweiten Reihe fallen in die falsche Richtung."},"air":[[0,15]],"figures":[{"cast":"plf","framing":"medium","mood":"dizzy","pose":"stand","facing":"front","x":0.5,"y":0.62,"h":0.55}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":66},"text":{"de":"Kleine, fast unmerkliche Verzerrungen. Als wäre sie gefangen in einer Welt, die nicht ganz real war."}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Reaktions-Beat in der Mitte (Owner 2026-10-10: mehr Shots in die Mitte). „… nicht mehr zu wissen, was wahr war und was nicht“ steckt im Bild (die falschen Schatten)."},{"id":"sb-35-8","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"cu","angle":"low"},"location":"graveyard","view":"real","light":{"key":"top-right","height":"high","soft":0.6,"note":{"de":"Die Sonne direkt aufs Gesicht, Augen geschlossen: eine weiße, warme Hälfte – die andere Hälfte zerfällt in versetzte Streifen."}},"action":{"de":"PLF hebt das Gesicht in die Sonne, Augen geschlossen, ein kurzer Moment Ruhe. Die eine Gesichtshälfte ist klar, die andere in waagrechte Streifen zerschnitten und um einige Pixel verschoben."},"air":[[0,25]],"figures":[{"cast":"plf","framing":"cu","mood":"acceptance","pose":"stand","facing":"front","x":0.5,"y":0.6,"h":0.85}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":64},"text":{"de":"Das Sonnenlicht wärmte ihre Haut und beruhigte die Nerven – für einen kurzen Moment."}},{"variant":"narration","font":"mono","rect":{"x":56,"y":88,"width":38},"text":{"de":"Doch die Störungen blieben."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-35-9","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"high"},"location":"graveyard","view":"real","light":{"note":{"de":"Harte Sonne; wo Teile fehlen, ist reines Weiß – keine Schatten, kein Boden."}},"action":{"de":"Der Friedhof springt: ein Grabstein steht doppelt, sein Zwilling zwei Reihen weiter; eine Grabvase hängt halb in der Luft; ein Stück Mauer fehlt, dahinter reines Weiß. Nach unten zerfällt der Boden in grobe Pixelblöcke und dann in leeres Weiß."},"air":[[78,100]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"stand","facing":"away","x":0.3,"y":0.5,"h":0.15}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":62},"text":{"de":"Teile der Umgebung verschwanden plötzlich und tauchten an anderer Stelle wieder auf."}},{"variant":"narration","font":"mono","rect":{"x":34,"y":58,"width":60},"text":{"de":"Der Friedhof wirkte wie eine digitale Illusion, die in der nächsten Sekunde zusammenbrechen könnte."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Weißes Ende = Luft vor Szene 36."}]}],"notes":["Zeilen im Skript (1-basiert) in source.lines: 1478–1505.","Kapiteltitel wie in Kapitel 2 (die fünf Trauerphasen): Titel-Shot am Anfang (Owner 2026-10-10).","PLF durchgehend „sie“ – als geschlechtsneutrale Form; im Deutschen gibt es keine gute (Owner 2026-10-10).","Frage an den Owner: Tageszeit. Kapitel 3 endet (sb-34-7) bei „day“; „klarer Himmel“ und „Sonnenlicht“ passen. Hier harte, hohe Sonne gesetzt.","Gekürzt: „ein Ort, der in der nächsten Sekunde zusammenbrechen könnte“ wörtlich behalten; „Ein Glitch … der ihm immer wieder das Gefühl gab, nicht mehr zu wissen, was wahr war“ steckt im Bild (sb-35-7, falsche Schatten).","Glitches in Schwarzweiß: versetzte Bildstreifen, Pixelblöcke, Treppenkanten, doppelte Objekte, weiße Löcher – kein RGB-Versatz (Sin-City-Regel).","Perspektive Szene 35: durchgehend real – PLF (human) nach dem Kampf; die Krähen nur als Nachhall (Liniengrafik)."]},{"storyboard":2,"toon":"catpope","chapter":4,"source":{"script":"script:catpope:de","scene":36,"heading":"EXT. FRIEDHOF","lines":[1506,1567]},"cast":[{"ref":"plf","character":"catpope","persona":"human","look":"default"},{"ref":"sphynx","character":"catpope","persona":"cat","look":"default"},{"ref":"catpope","character":"catpope","persona":"regular","look":"default"}],"locations":[{"ref":"graveyard","place":"graveyard","time":"day"}],"light":{"key":"top-left","height":"high","source":"sun","shadow":"short","soft":0.5,"note":{"de":"Dieselbe harte Sonne wie in Szene 35; die Glitches schneiden Licht und Schatten in versetzte Streifen."}},"groups":[{"label":"scene-36","renderer":{"type":"vertical"},"continues":true,"shots":[{"id":"sb-36-1","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","action":{"de":"Zwischen zwei Reihen schiefer Grabsteine: PLF geht suchend den Kiesweg entlang, beugt sich zu einem Stein. Ein Grabstein links ist nur noch ein gestrichelter Umriss, durch den man die Mauer sieht."},"air":[[0,20]],"figures":[{"cast":"plf","framing":"full","mood":"thinking","pose":"walk","facing":"three-quarter-left","x":0.55,"y":0.62,"h":0.35}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":50},"text":{"de":"36 EXT. FRIEDHOF"}},{"variant":"narration","font":"mono","rect":{"x":30,"y":80,"width":64},"text":{"de":"PLF begann ihre Erkundung, aber die Glitches erschwerten die Suche. Die Realität schien sich willkürlich zu verschieben."}}],"source":{"type":"schematic","want":"photo"},"status":"draft","note":"Luft oben = Szenenwechsel (anschließend an das Weiß von sb-35-9)."},{"id":"sb-36-2","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"real","light":{"note":{"de":"Oben: Grabstein mit hartem Schatten. Unten: derselbe Fleck, Schatten ohne Stein – der Schatten bleibt einen Moment länger."}},"action":{"de":"Zweimal derselbe Bildausschnitt übereinander: oben ein verwitterter Grabstein, PLF streckt die Hand danach aus. Unten dieselbe Stelle – der Stein ist weg, nur sein Schatten liegt noch im Gras und eine Wolke Pixelstaub, PLFs Hand greift ins Leere."},"air":[[44,56]],"figures":[{"cast":"plf","framing":"medium","mood":"neutral","pose":"reach","facing":"right","x":0.25,"y":0.25,"h":0.4},{"cast":"plf","framing":"medium","mood":"surprised","pose":"reach","facing":"right","x":0.25,"y":0.8,"h":0.4}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":46,"y":8,"width":46},"text":{"de":"Ein Grabstein, gerade noch da."}},{"variant":"narration","font":"mono","rect":{"x":56,"y":62,"width":34},"text":{"de":"Verschwunden."}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Zwei Bilder im Bild (wie in Kapitel 2), dazwischen ein weißer Streifen als Luft. Der zurückbleibende Schatten ist der Witz des Glitchs."},{"id":"sb-36-3","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"low"},"location":"graveyard","view":"real","light":{"key":"back","height":"high","rim":true,"note":{"de":"Gegenlicht durch die Zypressen: drei versetzte schwarze Silhouetten derselben Bäume, jede mit eigenem Lichtrand."}},"action":{"de":"Untersicht auf eine Gruppe Zypressen: ihre Umrisse flackern in drei leicht versetzten Kopien, wie in verschiedene Dimensionen gezogen. PLF klein am unteren Rand, den Kopf im Nacken."},"air":[[0,15]],"figures":[{"cast":"plf","framing":"full","mood":"confused","pose":"stand","facing":"away","x":0.5,"y":0.9,"h":0.18}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":8,"y":6,"width":64},"text":{"de":"Die Umrisse der Bäume flackerten, als würden sie in verschiedene Dimensionen versetzt."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Neuer Beat in der Mitte (Owner 2026-10-10): das Skript nennt die Bäume eigens."}]},{"label":"scene-36-cat","renderer":{"type":"horizontal","params":{"endless":true}},"continues":true,"shots":[{"id":"sb-36-4","format":"loop360","aspect":"3:1","projection":"perspective","move":"look-around","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","light":{"note":{"de":"Harte Sonne rundum; wo die Katze aufblitzt, reißt ein weißer Störstreifen durchs Bild."}},"action":{"de":"360°-Panorama des Friedhofs: Grabreihen, Zypressen, die Mauer, die Gruft, ein verwittertes Tor am Rand (für Szene 37). Die nackte Sphynx-Katze taucht an drei Stellen gleichzeitig auf – auf einem Grabstein, halb in einem Störstreifen, als Umriss im Tor –, jedes Mal leicht verpixelt. PLF auf einer Seite, sich umdrehend."},"air":[],"figures":[{"cast":"plf","framing":"full","mood":"confused","pose":"look-back","facing":"three-quarter-right","x":0.12,"y":0.62,"h":0.3},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"sit","facing":"front","x":0.38,"y":0.45,"h":0.12},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"stand","facing":"left","x":0.62,"y":0.7,"h":0.12},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"sit","facing":"front","x":0.88,"y":0.55,"h":0.1}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":1,"y":10,"width":14},"text":{"de":"Zwischen den flimmernden Szenen tauchte immer wieder die Sphynx-Katze auf – wie eine lebende Anomalie."}},{"variant":"narration","font":"mono","rect":{"x":51,"y":10,"width":14},"text":{"de":"Sie schien durch die Fehler im System hindurchzugleiten."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Der Loop passt hier wirklich: „wo ist die Katze?“ – der Leser sucht sie beim Ziehen wie PLF. Die Sphynx-Katze = catpope / cat, also PLF selbst (Kapitel 5: „Ich war die Katze!“) – wie der Tiger in Kapitel 3; hier noch nicht verraten, nur dieselbe Haltung (sb-36-7). Das Tor hier schon zeigen (Szene 37: „ein Tor, das PLF zuvor kaum beachtet hatte“).","prompt":{"en":"Seamless 360-degree panorama of a small walled graveyard at noon: rows of crooked headstones, cypress trees, a stone crypt, the wall, a weathered wrought-iron gate at the edge. A hairless sphynx cat appears at three places at once: on a headstone, half inside a horizontal glitch band, as an outline in the gate. A person in a white robe turns around on one side. Hard sun, crisp black shadows."}}]},{"label":"scene-36-b","renderer":{"type":"vertical"},"continues":true,"shots":[{"id":"sb-36-5","format":"vertical","aspect":"1:4","projection":"top-down","move":"travel","shot":{"size":"wide","angle":"bird"},"location":"graveyard","view":"real","light":{"key":"left","height":"high","shadow":"long","note":{"de":"Von oben: die Schatten der Grabsteine als schwarze Balken quer über den Weg – PLF springt über sie hinweg."}},"action":{"de":"Von oben, den Kiesweg entlang tief in den Friedhof: oben die Katze, die vorausläuft, darunter PLF im Lauf. In der Mitte ist ein Streifen des Wegs samt Gräbern seitlich versetzt wie ein verrutschter Bildstreifen; PLF erscheint davor und dahinter, als Bewegungsspur."},"air":[[0,8]],"figures":[{"cast":"sphynx","framing":"full","mood":"neutral","pose":"run","facing":"away","x":0.6,"y":0.12,"h":0.08},{"cast":"plf","framing":"full","mood":"confused","pose":"run","facing":"away","x":0.45,"y":0.72,"h":0.15}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":32,"width":56},"text":{"de":"Verwirrt und zunehmend verunsichert versuchte PLF, der Katze zu folgen."}},{"variant":"narration","font":"mono","rect":{"x":50,"y":88,"width":44},"text":{"de":"Tief in den Friedhof führte die Jagd."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Die Jagd: der Scroll ist der Lauf.","prompt":{"en":"Top-down view along a gravel path deep into a walled graveyard, rows of headstones on both sides casting long black shadow bars across the path. A hairless sphynx cat runs ahead near the top, a person in a white robe runs after it lower down. In the middle a horizontal strip of the path and graves is shifted sideways like a misaligned image slice. Hard sun."}},{"id":"sb-36-6","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"full","angle":"dutch"},"location":"graveyard","view":"real","light":{"note":{"de":"Zwei PLFs, zwei Schatten in verschiedene Richtungen – das Licht widerspricht sich selbst."}},"action":{"de":"Gekipptes Bild: PLF mitten im Schritt zweimal – einmal am Weg, einmal halb durchsichtig zwei Reihen weiter am Tor, als wäre sie für einen Sekundenbruchteil dorthin versetzt worden. Der Boden in waagrechten Rucken versetzt."},"air":[[0,15]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"run","facing":"right","x":0.35,"y":0.6,"h":0.35},{"cast":"plf","framing":"full","mood":"scared","pose":"run","facing":"right","x":0.75,"y":0.42,"h":0.22,"note":"halb durchsichtig, versetzt"}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":70},"text":{"de":"Der Boden schien zu ruckeln, sie an einen anderen Ort zu versetzen – und Sekundenbruchteile später zurück."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-36-7","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"real","light":{"note":{"de":"Die Katze im Hintergrund scharf und ruhig im Licht, PLF vorne außer Atem, ihr Schatten unter ihr gestaucht."}},"action":{"de":"PLF bleibt keuchend stehen, Hände auf den Knien. Im Hintergrund, auf einem flachen Grabstein, sitzt die Sphynx-Katze ruhig und schaut ihr zu – in genau derselben vorgebeugten Haltung wie PLF."},"air":[[0,18]],"figures":[{"cast":"plf","framing":"medium","mood":"dizzy","pose":"crouch","facing":"front","x":0.35,"y":0.65,"h":0.55},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"sit","facing":"front","x":0.75,"y":0.42,"h":0.12}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":40,"y":84,"width":54},"text":{"de":"Nichts hier folgte den Regeln der normalen Welt."}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Reaktion in der Mitte (Owner 2026-10-10). Die gespiegelte Haltung lässt den Leser ahnen, dass die Katze PLF ist (wie beim Tiger in Kapitel 3) – ohne es zu sagen."},{"id":"sb-36-8","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"cu","angle":"low"},"location":"graveyard","view":"real","light":{"key":"left","height":"low","shadow":"long","note":{"de":"Streiflicht über die Gravur: jede Kerbe ein schwarzer Strich, PLFs Augen im Schatten des Steins."}},"action":{"de":"PLF kniet vor einem Grabstein, das Gesicht nah am Stein. Die eingemeißelten Lettern verschwimmen und zittern, die Kanten zerfasern in Pixelstufen. In ihren Augen Furcht."},"air":[[0,10]],"figures":[{"cast":"plf","framing":"cu","mood":"scared","pose":"kneel","facing":"three-quarter-right","x":0.35,"y":0.6,"h":0.75}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":44,"y":6,"width":52},"text":{"de":"Dann, inmitten dieser Störsignale, machte PLF eine Entdeckung. Furcht überkam sie."}},{"variant":"narration","font":"mono","rect":{"x":50,"y":86,"width":44},"text":{"de":"Die Lettern verschwammen vor ihren Augen."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-36-9","format":"vertical","aspect":"1:4","projection":"perspective","move":"tilt-down","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"left","height":"low","shadow":"long","note":{"de":"Streiflicht von links über eine Reihe Grabsteine: jede Inschrift scharf ausgeschnitten, die Schatten fallen nach rechts ins Leere."}},"action":{"de":"Eine Reihe gleicher Grabsteine untereinander, einer pro Abschnitt. Auf jedem statt eines Namens nur eine Funktion, eingemeißelt (siehe Texte). Keine Daten, keine Bilder, keine Blumen."},"air":[[0,6]],"figures":[],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":3,"width":60},"text":{"de":"Da standen keine Namen – nur Funktionen!"}},{"variant":"caption","font":"lettering","rect":{"x":20,"y":18,"width":60},"text":{"de":"WÄCHTER:IN"}},{"variant":"caption","font":"lettering","rect":{"x":20,"y":40,"width":60},"text":{"de":"KRIEGER:IN"}},{"variant":"caption","font":"lettering","rect":{"x":20,"y":62,"width":60},"text":{"de":"BERATER:IN"}},{"variant":"caption","font":"lettering","rect":{"x":20,"y":84,"width":60},"text":{"de":"INFLUENCER"}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Die Inschriften als Lettering auf den Steinen (in den Text-Boxen, damit sie übersetzbar bleiben – das Bild selbst ohne Schrift). „AI Ethiker:in“ bekommt den nächsten Shot für sich."},{"id":"sb-36-10","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"ecu","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"left","height":"low","shadow":"long","note":{"de":"Streiflicht: der Finger wirft einen langen Schatten in die Kerbe; wo er hinkommt, zerfällt die Schrift."}},"action":{"de":"Ganz nah: PLFs Fingerkuppe fährt die eingemeißelte Inschrift nach. Unter dem Finger zerfallen die Buchstaben in Pixelstufen und setzen sich versetzt wieder zusammen."},"air":[[0,20]],"figures":[{"cast":"plf","framing":"ecu","mood":"scared","pose":"reach","facing":"right","x":0.3,"y":0.6,"h":0.5,"note":"nur Hand und Unterarm"}],"dialog":[{"variant":"caption","font":"lettering","rect":{"x":18,"y":44,"width":66},"text":{"de":"AI ETHIKER:IN"}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Detail in der Mitte (Owner 2026-10-10). Die letzte und modernste Funktion bekommt das Gewicht."},{"id":"sb-36-11","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"ews","angle":"high"},"location":"graveyard","view":"real","light":{"key":"top-left","height":"high","note":{"de":"Von schräg oben: endlose Reihen gleicher Steine, gleiche Schatten – ein Raster wie Server-Racks."}},"action":{"de":"Hohe Totale: der Friedhof dehnt sich unmöglich weit, Reihe um Reihe identischer Grabsteine bis zum Horizont, streng im Raster (Anklang an die Server-Racks aus Kapitel 3). PLF ein einzelner weißer Punkt in einer Gasse."},"air":[[0,20]],"figures":[{"cast":"plf","framing":"full","mood":"sad","pose":"stand","facing":"away","x":0.5,"y":0.78,"h":0.05}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":24,"width":50},"text":{"de":"Rollen in einer grotesken Hierarchie."}},{"variant":"narration","font":"mono","rect":{"x":36,"y":86,"width":58},"text":{"de":"Kein einziger Name, keine Identität. Nur Positionen, wie in einem undurchdringlichen System."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","prompt":{"en":"High wide view over an impossibly vast graveyard: row after row of identical headstones in a strict grid all the way to the horizon, like rows of server racks. A single tiny person in a white robe stands in one aisle. Hard noon sun, identical short black shadows."}},{"id":"sb-36-12","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"full","angle":"eye"},"location":"graveyard","view":"real","light":{"note":{"de":"Das Bild reißt in Streifen: Licht und Schatten springen von Streifen zu Streifen."}},"action":{"de":"PLF hastet weiter zwischen den Gräbern, das Gewand flattert. Das Bild ist in grobe waagrechte Streifen zerrissen, jeder zeigt sie einen Schritt versetzt; nach unten werden die Risse breiter."},"air":[[0,10]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"run","facing":"right","x":0.5,"y":0.5,"h":0.4}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":62},"text":{"de":"Angsterfüllt lief sie hastig weiter, in der Hoffnung auf Gräber, die mehr verraten würden."}},{"variant":"narration","font":"mono","rect":{"x":40,"y":82,"width":54},"text":{"de":"Die Glitches wurden intensiver. Die Realität selbst reagierte."}}],"source":{"type":"schematic","want":"art"},"status":"draft"},{"id":"sb-36-13","format":"vertical","aspect":"1:4","projection":"perspective","move":"reveal","shot":{"size":"wide","angle":"low"},"location":"graveyard","view":"real","light":{"key":"back","height":"high","rim":true,"shadow":"long","note":{"de":"Die Grabmäler der Patriarchen ragen schwarz gegen die Sonne, die Inschriften nur als weiße Kerben im Gegenlicht."}},"action":{"de":"Von unten nach oben auftauchend: monumentale Grabmäler der Kirchenpatriarchen, Obelisken und Sarkophage mit Mitren und Kreuzstäben. Auf jedem nur ein einziges Wort, immer wieder (siehe Texte). PLF klein davor."},"air":[[0,14]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"stand","facing":"away","x":0.5,"y":0.92,"h":0.18}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":16,"width":62},"text":{"de":"Schließlich die Gräber der Kirchenpatriarchen. Wieder keine Namen – nur ein einziges Wort. Immer und immer wieder."}},{"variant":"caption","font":"lettering","rect":{"x":10,"y":40,"width":30},"text":{"de":"POPE"}},{"variant":"caption","font":"lettering","rect":{"x":58,"y":50,"width":30},"text":{"de":"POPE"}},{"variant":"caption","font":"lettering","rect":{"x":30,"y":66,"width":30},"text":{"de":"POPE"}}],"source":{"type":"schematic","want":"photo"},"status":"draft","note":"Reveal: die Monumente wachsen beim Scrollen aus dem Licht."},{"id":"sb-36-14","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"cu","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"back","height":"eye","rim":true,"soft":0.35,"note":{"de":"PLF vor den Grabmälern im Gegenlicht: ein heller Rand um das Profil, das Gesicht fast schwarz."}},"action":{"de":"PLF im Profil, Hand vor dem Mund, die Befürchtung bestätigt. Hinter ihr unscharf die Grabmäler mit den vervielfachten POPE-Inschriften."},"air":[[0,12]],"figures":[{"cast":"plf","framing":"cu","mood":"scared","pose":"stand","facing":"left","x":0.55,"y":0.55,"h":0.8}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":60},"text":{"de":"PLFs Befürchtung wurde bestätigt. Keine Unterscheidung, keine Geschichte. Nur Titel."}},{"variant":"narration","font":"mono","rect":{"x":40,"y":84,"width":54},"text":{"de":"Als hätten diese Menschen nie existiert. Als Individuen ausgelöscht."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-36-15","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"back","height":"high","soft":0.3,"note":{"de":"Eine Welle aus weißem Rauschen läuft durch das Gegenlicht und frisst die Schatten."}},"action":{"de":"Stille Überleitung: eine Glitch-Welle läuft von links über die Reihe der Patriarchen-Grabmäler, ein Band aus Pixelrauschen; wo sie war, wackeln die Inschriften und beginnen sich umzuschreiben."},"air":[[0,30]],"figures":[],"dialog":[],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Geplante Stille (Owner 2026-10-10: mehr Luft in der Mitte): der Atemzug vor dem Umschreiben der Titel."},{"id":"sb-36-16","format":"vertical","aspect":"1:4","projection":"perspective","move":"tilt-down","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"left","height":"low","shadow":"long","note":{"de":"Streiflicht auf den Inschriften; die neuen Titel flackern hell aus den Kerben, als wären sie Bildschirmschrift."}},"action":{"de":"Die POPE-Inschriften auf den Grabmälern verwandeln sich im Glitch, Stein für Stein, in moderne Titel (siehe Texte) – die Buchstaben halb gemeißelt, halb Bildschirmschrift."},"air":[[0,6]],"figures":[],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":3,"width":56},"text":{"de":"Selbst die Titel veränderten sich inmitten der Glitches."}},{"variant":"caption","font":"lettering","rect":{"x":12,"y":18,"width":30},"text":{"de":"CEO"}},{"variant":"caption","font":"lettering","rect":{"x":54,"y":32,"width":34},"text":{"de":"GURU"}},{"variant":"caption","font":"lettering","rect":{"x":8,"y":48,"width":66},"text":{"de":"MODERATOR:IN"}},{"variant":"caption","font":"lettering","rect":{"x":20,"y":64,"width":74},"text":{"de":"THOUGHT LEADER:IN"}},{"variant":"caption","font":"lettering","rect":{"x":6,"y":82,"width":80},"text":{"de":"STARTUP-GRÜNDER:IN"}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Das Skript: Titel „nicht nur alt, sondern auch modern und aus der digitalen Welt“ – im Bild der Übergang Stein → Bildschirm."},{"id":"sb-36-17","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"narration","light":{"key":"right","height":"low","shadow":"long","note":{"de":"Cat Pope außerhalb der Szene: Streiflicht von rechts, hinter ihm der Friedhof als schwarzer Scherenschnitt."}},"action":{"de":"Cat Pope – die Erzählstimme aus der Zukunft, als Cat Pope oder mit Katzenmaske – sitzt auf der Friedhofsmauer, den Rücken zum Friedhof, und spricht direkt zum Leser. Dahinter der Friedhof als flacher schwarzer Scherenschnitt, die Grabsteine wie Säulen eines Archivregals."},"air":[[0,15]],"figures":[{"cast":"catpope","framing":"medium","mood":"thinking","pose":"sit","facing":"front","x":0.5,"y":0.62,"h":0.55}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":60},"text":{"de":"Der Friedhof war keine Ruhestätte – er war ein lebendiges Archiv."}},{"variant":"narration","font":"mono","rect":{"x":6,"y":18,"width":60},"text":{"de":"Als hätte sich die Hierarchie des Systems über die Jahrhunderte einfach nur angepasst."}},{"variant":"narration","font":"mono","rect":{"x":38,"y":86,"width":56},"text":{"de":"Individualität war längst durch Funktionen und Rollen ersetzt."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Die Deutung der Szene erzählt Cat Pope selbst (narration, regular) – wie in Kapitel 3 (sb-25-7). Weißer Grund unten = Luft vor Szene 37."}]}],"notes":["Zeilen im Skript (1-basiert) in source.lines: 1506–1567.","PLF ist im Kapitel nur Mensch (Priester, ohne Katzenmerkmale) oder Sphynx-Katze; Cat Pope selbst erst im Spiegel am Ende von Kapitel 5 (Owner 2026-10-10).","Frage an den Owner: Schreibweise „Spynx“ (Skript Szene 36) vs. „Sphynx“ (Szene 37) – „Sphynx“ gesetzt.","Frage an den Owner: die Inschriften stehen in Text-Boxen (Lettering), damit sie übersetzbar bleiben; das Bild selbst bleibt ohne Schrift. Oder sollen sie in den Stein (Bild) und pro Sprache neu gerendert werden?","Frage an den Owner: „Influencer“ ohne „:in“ (anders als die anderen Funktionen) – so aus dem Skript übernommen; Absicht?","Gekürzt: „Die Hoffnung, Gräber zu finden, die mehr verraten würden“ zu einem Satz mit „angsterfüllt“ (Skript: „Angsterfühlt“); „Die Realität selbst reagierte in diesem Moment reagierte“ zu „Die Realität selbst reagierte.“; „eine gespenstige Vision der Welt“ weggelassen (sb-36-17).","Owner 2026-10-10 („ungefähr 30 % länger“): zusätzliche Beats in der Mitte – sb-36-3 (Bäume), sb-36-7 (Reaktion, Katze schaut zu), sb-36-10 (Detail AI Ethiker:in), sb-36-15 (stille Überleitung).","Perspektive Szene 36: real – PLF (human) zwischen den Glitches; sb-36-17 narration – Cat Pope (regular) deutet den Friedhof."]},{"storyboard":2,"toon":"catpope","chapter":4,"source":{"script":"script:catpope:de","scene":37,"heading":"EXT. AM BRUNNEN","lines":[1568,1627]},"cast":[{"ref":"plf","character":"catpope","persona":"human","look":"default"},{"ref":"sphynx","character":"catpope","persona":"cat","look":"default"}],"locations":[{"ref":"well","place":"well","time":"day"},{"ref":"graveyard","place":"graveyard","time":"day"}],"light":{"key":"top-left","height":"high","source":"sun","shadow":"short","soft":0.5,"accent":{"color":"gold","on":"die Augen der Sphynx-Katze"},"note":{"de":"Die Sonne verliert die Ordnung: Schatten zeigen in verschiedene Richtungen, bis die Welt reißt. Die Katze hat ihr eigenes Licht (Aura) – die einzige feste Quelle; ihre goldenen Augen sind die einzige Farbe."}},"groups":[{"label":"scene-37","renderer":{"type":"vertical"},"continues":true,"shots":[{"id":"sb-37-1","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"full","angle":"eye"},"location":"well","view":"real","action":{"de":"Ein alter steinerner Brunnen mit rundem Becken am Rand des Friedhofs. PLF eilt darauf zu, schon vornübergebeugt, die Hand nach dem Wasser ausgestreckt."},"air":[[0,20]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"run","facing":"three-quarter-right","x":0.35,"y":0.6,"h":0.4}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":52},"text":{"de":"37 EXT. AM BRUNNEN"}},{"variant":"narration","font":"mono","rect":{"x":40,"y":84,"width":56},"text":{"de":"PLFs Atem ging schneller. Sie eilte zu einem Brunnen, um Wasser zu trinken."}}],"source":{"type":"schematic","want":"photo"},"status":"draft","note":"Luft oben = Szenenwechsel."},{"id":"sb-37-2","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"eye"},"location":"well","view":"real","light":{"soft":0.4,"note":{"de":"Durch die Risse fällt ein anderes Licht – von der anderen Seite, als würde dort eine zweite Sonne stehen."}},"action":{"de":"Die Welt um den Brunnen bricht auf wie Kontinentalplatten oder Eis auf dem Ozean: breite Schollen, die auseinanderdriften. Durch die Spalten scheint die andere Wirklichkeit – ein Lichtkegel, eine Spirale, Mikrochips und Maschinen, und Menschen, die Katzen sind. PLF am Beckenrand, mitten zwischen den Schollen."},"air":[[0,12]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"stand","facing":"front","x":0.5,"y":0.75,"h":0.3}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":14,"width":50},"text":{"de":"Doch alles begann immer heftiger zu ruckeln."}},{"variant":"narration","font":"mono","rect":{"x":40,"y":44,"width":56},"text":{"de":"Die Glitches wurden zu Rissen in ihrer Wahrnehmung, durch die eine zweite durchschimmerte."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Was die zweite Wirklichkeit zeigt, lässt das Skript offen (siehe notes) – hier bewusst unscharf.","prompt":{"en":"The ground around a stone fountain breaks apart like tectonic plates or sea ice into drifting floes. Through the cracks another world shines up: a cone of light, a spiral, microchips and machines, and people who are cats. A person in a white robe stands at the basin edge between the floes. Hard light from the cracks, pure black and white."}},{"id":"sb-37-3","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"cu","angle":"low"},"location":"well","view":"real","light":{"key":"top-left","height":"high","soft":0.4,"note":{"de":"Ein einzelner Glanzpunkt auf dem Tropfen, schwarzer Schatten darunter auf dem Wasser – das einzige Ding, das sauber beleuchtet ist."}},"action":{"de":"Ein Wassertropfen löst sich aus dem Becken und steigt langsam auf, eine vollkommene Kugel, unter ihr kräuselt sich das Wasser. Im Hintergrund unscharf PLFs Gesicht."},"air":[[0,30]],"figures":[{"cast":"plf","framing":"cu","mood":"surprised","pose":"stand","facing":"front","x":0.6,"y":0.85,"h":0.45}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":50},"text":{"de":"Ein Wassertropfen erhob sich aus dem Becken."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","prompt":{"en":"Close-up at a stone fountain basin: a single drop of water lifts off the surface and slowly rises as a perfect floating sphere, the water rippling below it. Out of focus behind it the face of a person. One hard sun from the top left, a single bright highlight on the sphere, a black shadow on the water."}},{"id":"sb-37-4","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"ecu","angle":"eye"},"location":"well","view":"real","light":{"key":"top-left","height":"high","note":{"de":"In der Kugel: das gespiegelte Licht der großen Kugel aus Kapitel 3 – derselbe weiße Glanz."}},"action":{"de":"Ganz nah die schwebende Wasserkugel: in ihr gekrümmt PLFs Gesicht und dahinter, wie eine Erinnerung, die riesige spiegelnde Kugel über dem Bergwald (sb-26-2)."},"air":[[0,15],[85,100]],"figures":[{"cast":"plf","framing":"cu","mood":"thinking","pose":"stand","facing":"front","x":0.5,"y":0.5,"h":0.3,"note":"nur als Spiegelung in der Kugel"}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":8,"y":72,"width":60},"text":{"de":"Er erinnerte an die Kugel, die PLF in den Bergen gesehen hatte."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Neuer Beat (Owner 2026-10-10): die Erinnerung an Kapitel 3 als Bild, nicht nur als Satz.","prompt":{"en":"Extreme close-up of a floating sphere of water: in its curved surface the reflected face of a person in a white robe and, behind it like a memory, a gigantic chrome sphere rising above a snowy mountain forest. Hard light, one bright highlight, pure black and white."}},{"id":"sb-37-5","format":"vertical","aspect":"1:4","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"high"},"location":"well","view":"real","light":{"note":{"de":"Die Kugel bleibt im festen Licht; ringsum springen Schatten und Flächen hin und her."}},"action":{"de":"Oben die Wasserkugel, ruhig und intakt. Nach unten verschiebt sich der Friedhof um sie herum: Grabreihen rutschen seitlich, die Mauer knickt ab, der Boden flackert zwischen Kies und Pixelrauschen. Unten PLF, die das Gleichgewicht sucht."},"air":[[0,8]],"figures":[{"cast":"plf","framing":"full","mood":"dizzy","pose":"slip","facing":"front","x":0.45,"y":0.85,"h":0.25}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":40,"y":24,"width":56},"text":{"de":"Während die Wasserkugel intakt blieb, verschob sich die Struktur des Friedhofs. Die gesamte Szene wurde instabil."}},{"variant":"narration","font":"mono","rect":{"x":6,"y":58,"width":60},"text":{"de":"Ein unheimliches, verzerrtes Rascheln – wie ein beschädigter Ton in einem gestörten Video."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Das Rascheln steht im Skript ohne {…} – Erzählung, kein SFX; als Grafik vielleicht Störstreifen-Wellen."},{"id":"sb-37-6","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"mcu","angle":"low"},"location":"well","view":"real","light":{"key":"bottom","height":"below","source":"sun","note":{"de":"Licht von unten aus dem Becken: das Gesicht von unten angeleuchtet, die Augen weit – die Erkenntnis als Bedrohung."}},"action":{"de":"PLF über das Becken gebeugt, von unten aus dem Wasser gesehen, die Wasserkugel zwischen ihr und der Kamera. Ihr Gesicht erstarrt: sie begreift, dass ihr eigener Zweifel es ausgelöst hat."},"air":[[0,10]],"figures":[{"cast":"plf","framing":"mcu","mood":"scared","pose":"crouch","facing":"front","x":0.5,"y":0.45,"h":0.7}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":8,"y":82,"width":60},"text":{"de":"PLF wusste, dass etwas Schreckliches angestoßen wurde. Sie war der Auslöser."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-37-7","format":"vertical","aspect":"1:4","projection":"polar","move":"descend","shot":{"size":"ews","angle":"bird"},"location":"graveyard","view":"real","light":{"key":"top","height":"overhead","shadow":"none","soft":0.3,"note":{"de":"Keine Richtung mehr: die Schatten drehen sich mit dem Strudel, Weiß und Schwarz in Spiralarmen."}},"action":{"de":"Der Friedhof krümmt sich zu einem Strudel: Bäume und Grabsteine wirbeln in Spiralen, verschwinden, tauchen verzerrt wieder auf, wild rotierend. Ganz innen, winzig, PLF."},"air":[[0,8]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"fall","facing":"front","x":0.5,"y":0.82,"h":0.06}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":10,"width":62},"text":{"de":"Doch bevor PLF einen klaren Gedanken fassen konnte, verzog sich die Welt erneut. Die Zeit selbst stand nun gegen sie."}},{"variant":"narration","font":"mono","rect":{"x":50,"y":40,"width":44},"text":{"de":"Die Welt löschte sich aus."}},{"variant":"narration","font":"mono","rect":{"x":6,"y":62,"width":58},"text":{"de":"Bäume und Grabsteine verschwanden, tauchten wieder auf. Verzerrt. Wild rotierend."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Polar aus dem Friedhofs-Panorama von sb-36-4 (gleiche Quelle, Transformation per Code).","prompt":{"en":"A graveyard panorama transformed into a polar vortex seen from above: cypress trees and headstones swirl in spiral arms toward the centre, distorted, some dissolving into pixel blocks. A tiny person in a white robe at the centre. Pure black and white, no clear light direction."}},{"id":"sb-37-8","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","light":{"source":"none","soft":0.2,"note":{"de":"Hinter den Rissen nur Schwarz – kein Licht, keine Quelle."}},"action":{"de":"Das Bild des Friedhofs bricht wie Eis auf dem Ozean: Schollen mit Gräbern und Zypressen driften auseinander, dazwischen Schwarz, an den Bruchkanten die andere Welt (Lichtkegel, Spirale, Schaltkreise). PLF klein auf einer der Schollen."},"air":[[40,70]],"figures":[{"cast":"plf","framing":"full","mood":"scared","pose":"arms-up","facing":"front","x":0.3,"y":0.82,"h":0.18}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":50,"y":6,"width":44},"text":{"de":"Das Gewebe der Realität selbst zerriss."}}],"source":{"type":"schematic","want":"art"},"status":"draft"},{"id":"sb-37-9","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"ews","angle":"eye"},"location":"graveyard","view":"real","light":{"source":"none","soft":0.1,"note":{"de":"Fast nur Schwarz; der Schrei der Katze ist das Licht – weiße Lettern im Nichts."}},"action":{"de":"Schwarzes Nichts mit ein paar treibenden Fetzen des Friedhofs. Quer durch das Bild schneidet das lange Miauen als riesige weiße Lettern."},"air":[[0,25],[80,100]],"figures":[],"dialog":[{"variant":"caption","font":"lettering","rect":{"x":4,"y":42,"width":92},"text":{"de":"MIAAAAAAAAUUUUU"}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Neuer Beat (Owner 2026-10-10): das Miauen bekommt einen Screen für sich – die Stille des Nichts vor dem Klang."},{"id":"sb-37-10","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"back","height":"eye","source":"energy","rim":true,"accent":{"color":"gold","on":"die Augen der Sphynx-Katze"},"note":{"de":"Die Katze leuchtet von sich aus: eine Aura als weißer Kranz um eine schwarze Silhouette; die goldenen Augen die einzige Farbe."}},"action":{"de":"Oben PLF, erstarrt, der Kopf ruckt zur Seite (Bewegungslinien). Nach unten der Blick am Rand des Sichtfelds entlang: dort steht die Sphynx-Katze, schlank, von einer Aura umgeben, scharf und fest, während alles um sie flackert. Goldene Augen."},"air":[[40,50]],"figures":[{"cast":"plf","framing":"mcu","mood":"surprised","pose":"look-back","facing":"three-quarter-right","x":0.35,"y":0.18,"h":0.45},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"stand","facing":"front","x":0.7,"y":0.8,"h":0.2}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":50,"y":3,"width":46},"text":{"de":"Ein langgezogenes Miauen – ein vertrauter Klang inmitten des Wahnsinns. PLF erstarrte."}},{"variant":"narration","font":"mono","rect":{"x":6,"y":56,"width":54},"text":{"de":"Dort, am Rande des Sichtfeldes, stand die Sphynx-Katze. Ihre goldenen Augen blitzten im flackernden Licht."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","prompt":{"en":"Top: a person in a white robe freezes and snaps the head to the side. Below, at the edge of a flickering, distorted graveyard: a slender hairless sphynx cat stands perfectly sharp and solid, surrounded by a glowing aura, golden eyes. Everything around it blurs and glitches. Black and white except the golden eyes."}},{"id":"sb-37-11","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"cu","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"back","height":"eye","source":"energy","rim":true,"note":{"de":"Die Aura als weißer Kranz, die Katze dunkel davor, die goldenen Augen leuchten."}},"action":{"de":"Die Sphynx-Katze nah: sie sitzt mit geschlossenen Pfoten, als meditiere sie, eine Handbreit über dem Boden schwebend. Um sie die Aura; dahinter flackert und bricht der Friedhof."},"air":[[0,15]],"figures":[{"cast":"sphynx","framing":"cu","mood":"neutral","pose":"sit","facing":"front","x":0.5,"y":0.55,"h":0.6}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":60},"text":{"de":"Sie wirkte fest und real, während alles andere flüchtig und brüchig war."}},{"variant":"narration","font":"mono","rect":{"x":52,"y":88,"width":42},"text":{"de":"Meditierte sie? Schwebte sie?"}}],"source":{"type":"schematic","want":"generated"},"status":"draft","prompt":{"en":"Close-up of a hairless sphynx cat sitting upright with paws together as if meditating, floating a hand\'s width above the ground, a white glowing aura around it, golden eyes. Behind it a graveyard flickering and breaking into glitch bands. Strong backlight, black and white except the golden eyes."}},{"id":"sb-37-12","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"medium","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"right","height":"eye","source":"energy","note":{"de":"Licht von der Katze (rechts): PLFs ausgestreckte Hand ist hell – und zerfällt, wo sie ins Licht greift."}},"action":{"de":"PLF streckt zögernd die Hand nach der Katze aus. Ihre Finger zerfallen in Pixelblöcke, wo sie in die Störung greifen; die Katze rechts im Bild bleibt vollkommen scharf."},"air":[[0,20]],"figures":[{"cast":"plf","framing":"medium","mood":"confused","pose":"reach","facing":"right","x":0.3,"y":0.6,"h":0.55},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"sit","facing":"left","x":0.82,"y":0.62,"h":0.15}],"dialog":[],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Stille Reaktion in der Mitte (Owner 2026-10-10): PLF zerfällt mit der Welt, die Katze nicht."},{"id":"sb-37-13","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"back","height":"low","rim":true,"shadow":"long","note":{"de":"Hinter dem Tor ein warmes, ruhiges Gegenlicht – der Garten ist die einzige Gegend mit einer festen Sonne."}},"action":{"de":"Die Katze dreht den Kopf zu einem verwitterten, rostigen Tor am Rand des Friedhofs, halb von Efeu überwachsen. Durch die Gitterstäbe ein Garten in ruhigem Licht – ungestört, scharf, während der Friedhof davor zerfällt."},"air":[[0,10]],"figures":[{"cast":"sphynx","framing":"full","mood":"neutral","pose":"stand","facing":"right","x":0.3,"y":0.35,"h":0.15}],"dialog":[{"variant":"caption","font":"lettering","rect":{"x":6,"y":10,"width":50},"text":{"de":"MIAAAUUU"}},{"variant":"narration","font":"mono","rect":{"x":50,"y":26,"width":46},"text":{"de":"Ein weiteres, tieferes Miauen, dieses Mal dringlich. Einladend."}},{"variant":"narration","font":"mono","rect":{"x":6,"y":64,"width":60},"text":{"de":"Es kam aus Richtung eines verwitterten Tors, das PLF zuvor kaum beachtet hatte. Es schien in einen Garten zu führen."}}],"source":{"type":"schematic","want":"photo"},"status":"draft"},{"id":"sb-37-14","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"full","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"front","height":"low","shadow":"long","note":{"de":"Vorne das ruhige Licht aus dem Garten auf PLFs Gesicht; hinter ihr Schwarz und Pixelrauschen ohne Licht."}},"action":{"de":"PLF von vorn, zwischen zwei Welten: hinter ihr verschlingen die Glitches den Friedhof (schwarzes Nichts, Pixelränder), vor ihr fällt das ruhige Licht des Gartens durch das Tor auf ihr Gesicht."},"air":[[0,18]],"figures":[{"cast":"plf","framing":"full","mood":"acceptance","pose":"stand","facing":"front","x":0.5,"y":0.6,"h":0.45}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":62},"text":{"de":"PLF spürte: Dies war der einzige Ausweg. Überall sonst hatten die Glitches fast alles verschlungen."}},{"variant":"narration","font":"mono","rect":{"x":36,"y":84,"width":58},"text":{"de":"Der Garten jenseits des Tors wirkte seltsam unberührt. Dort schien die Realität intakt."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-37-15","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"eye"},"location":"graveyard","view":"real","light":{"key":"front","height":"low","shadow":"long","rim":true,"note":{"de":"Das Gartenlicht in PLFs Rücken, ihr Schatten fällt lang in den zerfallenden Friedhof."}},"action":{"de":"Über PLFs Schulter: ein letzter Blick zurück auf den zerfallenden Friedhof – Gruft, Zypressen, Patriarchen-Grabmäler, halb schon Pixelstaub, der in Schwarz treibt."},"air":[[0,25]],"figures":[{"cast":"plf","framing":"medium","mood":"sad","pose":"look-back","facing":"away","x":0.2,"y":0.75,"h":0.6}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":46,"y":6,"width":48},"text":{"de":"Ein letzter Blick auf den zerfallenden Friedhof."}}],"source":{"type":"schematic","want":"art"},"status":"draft"},{"id":"sb-37-16","format":"vertical","aspect":"1:4","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"high"},"location":"graveyard","view":"real","light":{"key":"bottom","height":"low","shadow":"long","rim":true,"note":{"de":"Das Licht kommt jetzt von unten, aus dem Garten hinter dem Tor: die Buchstaben-Brücke wirft lange Schatten nach oben ins Schwarz."}},"action":{"de":"Über schwarzem Nichts spannt sich eine Brücke aus riesigen weißen Buchstaben – das Schnurren –, die nach unten in einem Gartentor endet. PLF zieht sich auf allen vieren daran entlang, Buchstabe für Buchstabe, die Katze schon am Tor."},"air":[[0,10],[90,100]],"figures":[{"cast":"plf","framing":"full","mood":"sad","pose":"crawl","facing":"away","x":0.45,"y":0.45,"h":0.15},{"cast":"sphynx","framing":"full","mood":"neutral","pose":"sit","facing":"front","x":0.6,"y":0.86,"h":0.08}],"dialog":[{"variant":"caption","font":"lettering","rect":{"x":6,"y":22,"width":88},"text":{"de":"SCHNURR"}},{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":56},"text":{"de":"Das Schnurren bildete eine Brücke, die in einem Gartentor endete."}},{"variant":"narration","font":"mono","rect":{"x":40,"y":70,"width":54},"text":{"de":"Mit letzter Kraft. Buchstabe für Buchstabe zerrt sich PLF hinein."}}],"source":{"type":"schematic","want":"art"},"status":"draft","note":"Die SFX ist die Brücke selbst (Lettering als Bild-Element; die Box trägt den übersetzbaren Text). Weißes Ende = Kapitelende."}]}],"notes":["Zeilen im Skript (1-basiert) in source.lines: 1568–1627.","Die andere Wirklichkeit (Owner 2026-10-10): Menschen sind Katzen, ein Lichtkegel, eine Spirale, Mikrochips und Maschinen scheinen durch; die Umgebung zerreißt wie Kontinentalplatten oder Eis auf dem Ozean.","Ihr Zweifel macht PLF zum Auslöser (Owner 2026-10-10).","Frage an den Owner: die Brücke aus dem Schnurren, „Buchstabe für Buchstabe“ – wörtlich als Lettering-Brücke gesetzt (sb-37-16). Passt das, oder ist es bildlich gemeint?","Die Lieder werden nicht gestoryboardet – sie gehören zur App, nicht zum Toon (Owner 2026-10-10).","Akzent: die goldenen Augen der Sphynx-Katze – die einzige Farbe der Szene.","Gekürzt: „wieso auch, dachte sie doch noch Antworten zu finden“ weggelassen; „Unwirklichkeiten“ und „Mit letzter Kraft“ als Bild / kurzer Satz.","Owner 2026-10-10 („ungefähr 30 % länger“): zusätzliche Beats in der Mitte – sb-37-4 (die Erinnerung an die Kugel), sb-37-9 (das Miauen im Nichts), sb-37-12 (PLF greift nach der Katze).","Perspektive Szene 37: real – die Welt zerfällt, die Katze (catpope / cat, PLF selbst) bleibt fest."]}]}', NULL, '2026-10-20 00:00:00', 'published', 'import (2026-10-20-storyboard-import)' FROM DUAL
