"y":0.2,"h":0.6}],"dialog":[{"variant":"caption","font":"lettering","rect":{"x":30,"y":3,"width":64},"text":{"de":"SCHNUFF SCHNUFF"}},{"variant":"narration","font":"mono","rect":{"x":6,"y":30,"width":58},"text":{"de":"Riechen. Grün. Grasig, erfrischend. Ein Gemüse, das nach einer Farbe riecht?"}},{"variant":"bubble","rect":{"x":50,"y":46,"width":40},"tail":"top-left","text":{"de":"Ha, Brechbohne!"}},{"variant":"narration","font":"mono","rect":{"x":30,"y":86,"width":64},"text":{"de":"Zweitens: hier riecht es nach Humus. Saftige kompostierte Erde. Check."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-38-22","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"cu","angle":"eye"},"location":"garden","view":"real","light":{"key":"right","height":"low","note":{"de":"Hartes Seitenlicht ins verzogene Gesicht: jede Falte ein schwarzer Strich."}},"action":{"de":"PLF, Augen noch geschlossen, verzieht das Gesicht: die Zunge halb heraus, Erde an den Lippen – sie hat etwas Bitteres geschmeckt."},"air":[[0,12]],"figures":[{"cast":"plf","framing":"cu","mood":"disgusted","pose":"crouch","facing":"front","x":0.5,"y":0.55,"h":0.85}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":4,"width":56},"text":{"de":"Nun fehlte nur noch der letzte Sinn. Das Schmecken."}},{"variant":"narration","font":"mono","rect":{"x":40,"y":76,"width":54},"text":{"de":"Es war bitter. Glutamatartig, ein wenig wie altes Fleisch."}},{"variant":"caption","font":"lettering","rect":{"x":6,"y":64,"width":30},"text":{"de":"BÄH"}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-38-23","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"full","angle":"high"},"location":"garden","view":"real","light":{"key":"right","height":"low","note":{"de":"Die Pfütze fängt den letzten hellen Himmel: ein weißer Spiegel im schwarzen Boden."}},"action":{"de":"PLF spuckt aus und reißt die Augen auf. Von oben: vor ihr auf dem Weg zwischen den Beeten eine Pfütze, die den hellen Abendhimmel spiegelt."},"air":[[0,15]],"figures":[{"cast":"plf","framing":"full","mood":"surprised","pose":"crouch","facing":"front","x":0.4,"y":0.45,"h":0.35}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":40,"y":84,"width":54},"text":{"de":"PLF spuckt und reißt die Augen auf. Vor ihr eine Pfütze."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-38-24","format":"vertical","aspect":"1:4","projection":"perspective","move":"tilt-down","shot":{"size":"medium","angle":"high"},"location":"garden","view":"real","light":{"key":"right","height":"low","note":{"de":"Oben PLF dunkel über der Pfütze; im Spiegelbild die Katze hell, vom Himmel angestrahlt."}},"action":{"de":"Oben PLF, der Mensch im weißen Gewand, über die Pfütze gebeugt. Nach unten die Wasseroberfläche – darin, wo ihr Spiegelbild sein müsste, Cat Pope: die Papstgestalt mit dem Kopf der Sphynx-Katze, die in derselben Haltung zurückschaut. Hier erkennt PLF sich selbst."},"air":[[0,8]],"figures":[{"cast":"plf","framing":"medium","mood":"surprised","pose":"crouch","facing":"front","x":0.5,"y":0.18,"h":0.45},{"cast":"catpope","framing":"medium","mood":"neutral","pose":"crouch","facing":"front","x":0.5,"y":0.72,"h":0.45,"note":"nur als Spiegelbild in der Pfütze – das einzige Mal, dass Cat Pope selbst im Kapitel erscheint"}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":34,"width":52},"text":{"de":"In der Reflexion erkannte PLF die Katze wieder."}},{"variant":"bubble","rect":{"x":40,"y":46,"width":52},"tail":"top","text":{"de":"Du bist es? Aber wie kann das sein? …"}},{"variant":"narration","font":"mono","rect":{"x":6,"y":92,"width":70},"text":{"de":"PLF starrte regungslos in die Pfütze, und langsam begann der geerdete Geist zu verstehen. Jetzt ergab alles Sinn."}}],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Die Auflösung: die Katze (catpope / cat) ist PLF. view real – das Spiegelbild zeigt die Wahrheit, nicht PLFs Glauben.","prompt":{"en":"Top: a human priest in a white papal robe crouches and leans over a puddle on a garden path at sunset. Below, in the water where the reflection should be, Cat Pope looks back up – the same person in the same robe and pose, but with the head of a hairless sphynx cat. Low hard sun from the right, the puddle bright with the evening sky, black ground."}},{"id":"sb-38-25","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"ecu","angle":"eye"},"location":"garden","view":"real","light":{"key":"right","height":"low","note":{"de":"Zwei Augenpaare übereinander, oben im Schatten, unten im Spiegel hell."}},"action":{"de":"Extrem nah, horizontal geteilt durch die Wasserlinie: oben die Augen des Menschen PLF, unten in der Pfütze die Augen von Cat Pope – Katzenaugen im Sphynx-Gesicht, exakt gespiegelt, derselbe Blick."},"air":[],"figures":[{"cast":"plf","framing":"ecu","mood":"surprised","pose":"crouch","facing":"front","x":0.5,"y":0.3,"h":0.5},{"cast":"catpope","framing":"ecu","mood":"neutral","pose":"crouch","facing":"front","x":0.5,"y":0.72,"h":0.5,"note":"nur als Spiegelbild in der Pfütze – das einzige Mal, dass Cat Pope selbst im Kapitel erscheint"}],"dialog":[],"source":{"type":"schematic","want":"generated"},"status":"draft","note":"Stiller Beat in der Mitte (Owner 2026-10-10): das Erkennen, ohne Text. Frage: die Katzenaugen hier golden wie in Kapitel 4 (dann wäre es eine zweite Akzentfarbe neben dem Blau)?","prompt":{"en":"Extreme close-up split horizontally by a water line: above, a person\'s eyes; below, mirrored in a puddle, the eyes of Cat Pope – a sphynx cat\'s face under the papal collar – exactly the same gaze. Low hard sun, pure black and white."}},{"id":"sb-38-26","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"full","angle":"high"},"location":"garden","view":"real","light":{"key":"right","height":"low","soft":0.4,"note":{"de":"Die Sonne ist weg bis auf einen Rand: PLF fast nur noch Silhouette, ihr Schatten verschmilzt mit dem Boden."}},"action":{"de":"PLF sackt neben der Pfütze in sich zusammen, sitzt in der Erde, die Arme hängen kraftlos. Ein langer Seufzer (Atemlinie)."},"air":[[0,25]],"figures":[{"cast":"plf","framing":"full","mood":"acceptance","pose":"sit","facing":"front","x":0.45,"y":0.62,"h":0.35}],"dialog":[{"variant":"narration","font":"mono","rect":{"x":6,"y":6,"width":62},"text":{"de":"PLF fehlte die Kraft, sich weiter zu wehren. Es sollte ja doch nichts mehr helfen."}}],"source":{"type":"schematic","want":"direct"},"status":"draft"},{"id":"sb-38-27","format":"vertical","aspect":"1:3","projection":"perspective","move":"tilt-down","shot":{"size":"wide","angle":"eye"},"location":"garden","view":"real","light":{"key":"back","height":"low","rim":true,"soft":0.3,"note":{"de":"Die Sonne ist untergegangen: nur ein heller Horizontstreifen, PLF und ihr Spiegelbild als zwei Silhouetten."}},"action":{"de":"PLF sitzt mit einem Seufzen am Rand der Pfütze, schwarze Silhouette vor dem letzten Licht. In der Pfütze ihr Spiegelbild: Cat Pope, in derselben Haltung – sie war die Katze, die ganze Zeit. Nach unten Dämmerung bis ins Schwarz."},"air":[[80,100]],"figures":[{"cast":"plf","framing":"full","mood":"acceptance","pose":"sit","facing":"three-quarter-right","x":0.4,"y":0.42,"h":0.3},{"cast":"catpope","framing":"full","mood":"acceptance","pose":"sit","facing":"three-quarter-right","x":0.4,"y":0.62,"h":0.2,"note":"nur als Spiegelbild in der Pfütze – das einzige Mal, dass Cat Pope selbst im Kapitel erscheint"}],"dialog":[{"variant":"bubble","rect":{"x":40,"y":6,"width":52},"tail":"bottom-left","text":{"de":"??????????????? !!!!!!!!!!!!!!!"}},{"variant":"bubble","rect":{"x":46,"y":24,"width":44},"tail":"bottom-left","text":{"de":"Ich war die Katze!"}}],"source":{"type":"schematic","want":"direct"},"status":"draft","note":"Kapitelende: das Schwarz unten = Luft (und Platz für das 6. Lied, siehe notes)."},{"id":"sb-38-28","format":"viewport","aspect":"9:16","projection":"perspective","move":"hold","shot":{"size":"wide","angle":"eye"},"location":"garden","view":"narration","light":{"source":"none","note":{"de":"Schwarz – nur das Bild aus Zeichen."}},"action":{"de":"Das Schlussbild: die ASCII-Grafik vom Ende des Skripts, weiß auf Schwarz, als Bild gesetzt – einfach, mit Spaß."},"figures":[],"dialog":[],"source":{"want":"art"},"status":"draft","note":"Owner 2026-10-10: „Die ascii graphik is spass. Das ist ein schluss bild. Einfach“ – das Bild liegt als generated/sb-38-28--g1.png bei."}]}],"notes":["Zeilen im Skript (1-basiert) in source.lines: 1641–1753.","Kapiteltitel wie in Kapitel 2 (die fünf Trauerphasen): Titel-Shot am Anfang (Owner 2026-10-10).","Szenen-Box: „38 EXT. GARTEN EDEN IM SONNENUNTERGANG“ statt „GARDEN EDEN IM SONNEN UNTERGANG“ (Skript) – bitte bestätigen.","Frage an den Owner: PLFs Grübeln (Zeilen 1643–1658) und die Aufzählung lesen sich wie Gedanken. Wie in Kapitel 3 als Sprechblasen gesetzt – oder Gedankenblasen / Erzählboxen?","Frage an den Owner: „Quadrobiing, also zu einem Quadrant gemacht“ – gesetzt als „zum Quadrobing gebracht“ (die russische Quadrobics-Welle: auf allen vieren wie ein Tier). Ist „Quadrant“ gewollt (Wortspiel) oder ein Tippfehler?","„5-4-3-3-2“ bleibt so (Owner 2026-10-10: ggf. Tippfehler, kann aber benutzt werden).","Frage an den Owner: was schmeckt PLF (bitter, wie altes Fleisch)? Das Skript sagt es nicht – im Bild nur Erde an den Lippen (sb-38-22).","Frage an den Owner: „OBI Gießkannen“ und „Yves Klein-blau“ – Marken- / Künstlername so lassen (vgl. „Apple Store“ in Kapitel 3)?","Die Lieder werden nicht gestoryboardet – sie gehören zur App, nicht zum Toon, wahrscheinlich als Musikvideo (Owner 2026-10-10). Die ASCII-Grafik ist das Schlussbild (sb-38-28).","Akzent: das Yves-Klein-Blau der Wasserspeicher (vom Skript ausdrücklich benannt) – die einzige Farbe der Szene. Das Licht ist hier bewusst etwas weicher (soft 0.6) als in Kapitel 3/4: Akzeptanz.","Korrigiert (Tippfehler im Skript): überwältigend, Gabardine, geschlossen, wehren, „Endlich wurde es ruhig“ (Skript: „würde es Ruhe“), „das Summen wurde tiefer“, „ergab alles Sinn“, Reflexion, „Ord-Nung“ (Skript: „In Ord Nung“ – als Stocken gelesen).","Gekürzt: „Bewältigungsmechanismen“-Absatz in zwei Boxen; „Durch ihre Finger glitten hochgewachsene Gräser“ zusammengezogen; „PLF zog die Arme zurück zum Körper“ im Bild.","Owner 2026-10-10 („ungefähr 30 % länger“): zusätzliche Beats in der Mitte – sb-38-3 (oben ist unten), sb-38-8 (kein Schnee), sb-38-20 (Stille), sb-38-25 (die Augen); sb-38-4 trägt den Katzenschatten als Vorahnung.","Perspektive Szene 38: real – PLF (human) im Garten; sb-38-6 narration (Cat Pope regular erklärt die Übung); sb-38-7 memory (der Tag als Collage). Die Katze (catpope / cat) erscheint nur als Schatten und Spiegelbild – sie ist PLF."]}]}', NULL, '2026-10-20 00:00:00', 'published', 'import (2026-10-20-storyboard-import)' FROM DUAL
